MonarchButtonGroup(orientation = Orientation.Vertical, label = "Zoom") {
    iconButton(contentDescription = "Zoom in", onClick = { zoom += 10 }) {
        MonarchIcon(SampleIcons.Plus, contentDescription = null)
    }
    iconButton(contentDescription = "Zoom out", onClick = { zoom -= 10 }) {
        MonarchIcon(SampleIcons.Dash, contentDescription = null)
    }
}
